"""Generate a local submission document without third-party Python dependencies."""
from pathlib import Path
from zipfile import ZipFile, ZIP_DEFLATED
from xml.sax.saxutils import escape
import argparse
p=argparse.ArgumentParser();p.add_argument('--first',default='firstname');p.add_argument('--last',default='lastname');p.add_argument('--url',default='https://ali-task-studio.vercel.app');a=p.parse_args()
root=Path(__file__).resolve().parents[1]
sections=[('Nextplay — Task Studio','Software Development | Kanban Task Board'),('Candidate',f'{a.first} {a.last}'),('Overview and design','A calm, responsive Kanban workspace with a dark charcoal palette and lavender accents, clear hierarchy, compact task cards with subtle hover lighting, smooth drag feedback, and focused task editing. Title and description are required; due dates are optional and default to N/A. A styled calendar, safe in-app confirmations, and an explanation of guest persistence make the workflow predictable. React and TypeScript handle the interface, dnd-kit provides drag interactions, and Supabase handles anonymous guest authentication and persistent task storage.'),('Live frontend',a.url),('Repository','https://github.com/alfatla002/New_Player_Games'),('Advanced features','Custom task labels with label filtering; case-insensitive title search and priority filtering; due-today and overdue indicators; task totals, completed totals, overdue totals and completion progress. Tasks can also be edited and deleted.'),('Local setup','Install Node.js 22+. Run npm ci. Copy .env.example to .env. Set VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY using only the public key. Run the SQL schema below in Supabase. Enable anonymous sign-ins under Authentication. Run npm run dev. Run npm run build for production.'),('Authentication and security','The app reuses an existing Supabase session or calls signInAnonymously. Every task stores its owner user_id. Four RLS policies limit reads and writes to auth.uid(). Public unauthenticated database access is revoked. Never place a Supabase service-role key in this app. Separate browser profiles represent distinct guests; clearing browser data loses access to an anonymous account.'),('Verification and current limitations','Production build and unit tests passed. Eight unit tests and 13 browser checks passed, covering CRUD, validation, calendar and optional dates, dragging, failed-write recovery, safe confirmations, keyboard controls, reduced motion, and mobile layout. Desktop and mobile screenshots were reviewed; live API security and persistence checks are complete. Supabase anonymous sign-in and the tasks table are operational. All 12 live API checks passed, covering distinct guest sessions, task creation, update, reload and deletion, cross-user read/update/delete denial, forged-owner insertion denial, ownership-transfer denial, unauthenticated access denial, and preservation of the original task after unauthorized requests. The temporary verification task was deleted. Without configuration, the application displays a clearly labeled browser-local demo. Source is published to GitHub. The production Vercel URL was verified accessible without a login prompt, and its JavaScript bundle contains the configured Supabase project and public key.'),('Tradeoffs and future work','Drag updates appear immediately and roll back on failed writes rather than relying on realtime subscriptions. Tasks use creation order rather than persisted manual ordering. Add cross-session conflict handling, guest account linking, team assignees, activity history, comments, and live automated security tests with more time.'),('Complete database schema',(root/'supabase/migrations/202611080001_tasks.sql').read_text())]
def paragraph(text,bold=False):
 return '<w:p><w:r>'+('<w:rPr><w:b/><w:color w:val="7561B9"/></w:rPr>' if bold else '')+'<w:t xml:space="preserve">'+escape(text)+'</w:t></w:r></w:p>'
body=''.join(paragraph(title,True)+''.join(paragraph(line) for line in text.splitlines())+paragraph('') for title,text in sections)
xml='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>'+body+'<w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1080" w:right="1080" w:bottom="1080" w:left="1080"/></w:sectPr></w:body></w:document>'
output=root/'artifacts'/f'{a.first.lower()}_{a.last.lower()}_task_manager_assessment.docx';output.parent.mkdir(exist_ok=True)
with ZipFile(output,'w',ZIP_DEFLATED) as z:
 z.writestr('[Content_Types].xml','<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>')
 z.writestr('_rels/.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>')
 z.writestr('word/document.xml',xml)
print(output)
